// Golden-output test harness.
//
// Prints a deterministic text report describing what the searcher predicts for
// a fixed set of seeds and filter settings. The report generated by the
// ORIGINAL code is checked in as tests/golden_expected.txt; any later change
// (refactor, optimisation) must reproduce it byte-for-byte.
//
// Usage:  golden > out.txt && diff tests/golden_expected.txt out.txt
//
// The report has three sections:
//   [facts]   per-seed game facts (tags, vouchers, packs, shop, soul joker)
//   [filters] for each filter config: how many seeds in a fixed range pass,
//             a hash of exactly which ones, and the first few hits
//   [search]  first hit found by a single-threaded search from a start seed

#include "../src/functions.hpp"
#include "../src/search.hpp"
#include "filter_adapter.hpp"

#include <cstdint>
#include <cstdio>
#include <string>
#include <vector>

static std::string name(Item i) { return itemToString(i); }

// Each helper takes Instance BY VALUE, exactly like filter() does, so every
// query starts from a fresh RNG state for that seed.
static std::string facts(Instance inst) {
  std::string out = inst.seed.tostring();
  out += " | tag1=" + name(inst.nextTag(1));
  out += " | voucher1=" + name(inst.nextVoucher(1));
  // nextBoss() is excluded: the original code read uninitialised memory.
  // It has its own test now (tests/boss_test.cpp).
  return out;
}

static std::string packFacts(Instance inst) {
  std::string out = "packs=";
  for (int p = 0; p < 4; p++) out += name(inst.nextPack(1)) + ",";
  return out;
}

static std::string shopFacts(Instance inst) {
  std::string out = "shop=";
  for (int i = 0; i < 6; i++) {
    ShopItem it = inst.nextShopItem(1);
    out += name(it.item);
    if (it.type == Item::T_Joker) out += "(" + name(it.jokerData.edition) + ")";
    out += ",";
  }
  return out;
}

static std::string arcanaFacts(Instance inst) {
  std::string out = "mega_arcana=";
  auto cards = inst.nextArcanaPack(5, 1);
  for (auto c : cards) out += name(c) + ",";
  JokerData soul = inst.nextJoker(ItemSource::Soul, 1, true);
  out += " soul=" + name(soul.joker) + "(" + name(soul.edition) + ")";
  return out;
}

static std::string buffoonFacts(Instance inst) {
  std::string out = "buffoon=";
  auto jokers = inst.nextBuffoonPack(4, 1);
  for (auto &j : jokers) out += name(j.joker) + "(" + name(j.edition) + "),";
  return out;
}

// One filter configuration to exercise. Field order mirrors brainstorm().
struct NamedConfig {
  const char *label;
  TestConfig cfg;
};

static std::vector<NamedConfig> configs() {
  std::vector<NamedConfig> v;
  auto base = [] {
    TestConfig c;
    c.tag = Item::RETRY;
    c.voucher = Item::RETRY;
    c.pack = Item::RETRY;
    c.souls = 0;
    return c;
  };
  TestConfig c;

  c = base(); c.tag = Item::Charm_Tag;                     v.push_back({"charm", c});
  c = base(); c.tag = Item::Double_Tag;                    v.push_back({"double", c});
  c = base(); c.tag = Item::Charm_Tag; c.souls = 1;        v.push_back({"charm+soul", c});
  c = base(); c.tag = Item::Charm_Tag; c.souls = 1; c.perkeo = true;
                                                           v.push_back({"charm+soul+perkeo", c});
  c = base(); c.voucher = Item::Overstock;                 v.push_back({"overstock", c});
  c = base(); c.voucher = Item::Telescope; c.tag = Item::Double_Tag;
                                                           v.push_back({"telescope+double", c});
  c = base(); c.pack = Item::Mega_Arcana_Pack;             v.push_back({"mega_arcana", c});
  c = base(); c.pack = Item::Buffoon_Pack; c.tag = Item::Uncommon_Tag;
                                                           v.push_back({"buffoon+uncommon", c});
  c = base(); c.observatory = true;                        v.push_back({"observatory", c});
  c = base(); c.copymoney = true;                          v.push_back({"copymoney", c});
  c = base(); c.bean = true;                               v.push_back({"bean", c});
  c = base(); c.burglar = true;                            v.push_back({"burglar", c});
  c = base(); c.retcon = true;                             v.push_back({"retcon", c});
  return v;
}

int main(int argc, char **argv) {
  // Smaller scan sizes when run with "quick" (used while iterating).
  bool quick = argc > 1 && std::string(argv[1]) == "quick";
  const long long FACT_SEEDS = quick ? 200 : 2000;
  const long long FILTER_SEEDS = quick ? 20000 : 200000;

  std::printf("[facts]\n");
  {
    Seed s("A1");
    Instance inst(s);
    for (long long i = 0; i < FACT_SEEDS; i++) {
      // Jump around the seed space so we cover 1..8 character seeds.
      Seed js((long long)(1 + (i * 1159053509ll) % 2318107019760ll));
      Instance ji(js);
      std::printf("%s | %s | %s | %s | %s\n", facts(ji).c_str(),
                  packFacts(ji).c_str(), shopFacts(ji).c_str(),
                  arcanaFacts(ji).c_str(), buffoonFacts(ji).c_str());
    }
  }

  std::printf("[filters] seeds=%lld from=AAAAAAAA\n", FILTER_SEEDS);
  for (auto &nc : configs()) {
    applyConfig(nc.cfg);
    Seed s("AAAAAAAA");
    Instance inst(s);
    long long hits = 0;
    uint64_t hash = 1469598103934665603ull;  // FNV-1a over passing seed IDs
    std::string first;
    for (long long i = 0; i < FILTER_SEEDS; i++) {
      if (runFilter(inst) >= 1) {
        hits++;
        uint64_t id = (uint64_t)s.getID();
        for (int b = 0; b < 8; b++) {
          hash ^= (id >> (b * 8)) & 0xff;
          hash *= 1099511628211ull;
        }
        if (hits <= 5) first += s.tostring() + ",";
      }
      inst.next();
    }
    std::printf("%-20s hits=%lld hash=%016llx first=%s\n", nc.label, hits,
                (unsigned long long)hash, first.c_str());
  }

  // End-to-end: the real Search class, one thread so the answer is
  // deterministic. Only for filters that hit often enough to stay fast.
  std::printf("[search]\n");
  for (auto &nc : configs()) {
    std::string l = nc.label;
    if (l == "charm+soul+perkeo" || l == "observatory")
      continue;
    applyConfig(nc.cfg);
    std::printf("%-20s %s\n", nc.label, searchOneThread("1A2B3C4D").c_str());
  }
  return 0;
}
